func deviconSvgFor*(name: string): string =
  ## The mark for a file `name` by its extension, or "" for none.
  var ext = name
  let dot = name.rfind('.')
  if dot >= 0: ext = name[dot + 1 .. ^1]
  ext = ext.toLowerAscii
  for (e, cp) in DeviconByExtension:
    if e == ext:
      for (c, svg) in DeviconSvgs:
        if c == cp: return svg
  ""
